import { test } from "node:test";
import assert from "node:assert/strict";
import { checkout } from "../src/checkout.mjs";

test("checkout incluye el campo phone del cliente", () => {
  const items = [{ price: 1000, qty: 1 }];
  const customer = { id: "c1", name: "Santino", email: "santino@example.com", phone: "12345678" };
  const result = checkout(items, customer);

  assert.equal(result.customer.phone, "12345678");
  assert.equal(result.customer.name, "Santino");
  assert.equal(result.subtotal, 1000);
});

